def _zstd_module():
    """Import the workspace-pinned dependency under python -I."""
    vendor = ROOT / "tools" / "python"
    if str(vendor) not in sys.path:
        sys.path.insert(0, str(vendor))
    try:
        import zstandard as zstd
    except ImportError as exc:
        raise RuntimeError(
            f"zstandard not found; expected the workspace dependency under {vendor}"
        ) from exc
    return zstd


def _stream_decompress(frame: bytes, limit: int) -> bytes:
    if not frame.startswith(ZSTD_MAGIC):
        raise ValueError(f"missing Zstandard frame: {frame[:8].hex()}")
    zstd = _zstd_module()
    with zstd.ZstdDecompressor().stream_reader(
        io.BytesIO(frame), read_across_frames=False
    ) as reader:
        result = reader.read(limit + 1)
    if len(result) > limit:
        raise ValueError(f"Zstandard output exceeds safety limit ({limit} bytes)")
    return result


class _DirectoryReader:
    def __init__(self, data: bytes):
        self.data = data
        self.pos = 0
        self.entries: list[dict[str, Any]] = []

    def take(self, count: int) -> bytes:
        if count < 0 or self.pos + count > len(self.data):
            raise ValueError(f"truncated FMF directory at 0x{self.pos:x}")
        value = self.data[self.pos : self.pos + count]
        self.pos += count
        return value

    def u32(self) -> int:
        return struct.unpack("<I", self.take(4))[0]

    def string(self) -> str:
        length = self.u32()
        if length > MAX_STRING_SIZE:
            raise ValueError(f"oversized FMF directory string: {length}")
        return self.take(length).decode("utf-8")

    def directory(self, parent: PurePosixPath = PurePosixPath(), depth: int = 0) -> None:
        if depth > 40:
            raise ValueError("FMF directory nesting exceeds 40")
        folder = self.string()
        current = parent / folder
        count = self.u32()
        if count > 100_000:
            raise ValueError(f"excessive FMF entry count: {count}")
        for _ in range(count):
            name, extension = self.string(), self.string()
            offset, packed, size, time1, time2 = struct.unpack("<5Q", self.take(40))
            path = current / (name + extension)
            if path.is_absolute() or ".." in path.parts:
                raise ValueError(f"unsafe FMF path: {path}")
            self.entries.append(
                {
                    "path": path.as_posix(),
                    "offset": offset,
                    "packed_size": packed,
                    "size": size,
                    "time_fields": [time1, time2],
                }
            )
        subdirectory_count = self.u32()
        if subdirectory_count > 100_000:
            raise ValueError(f"excessive FMF subdirectory count: {subdirectory_count}")
        for _ in range(subdirectory_count):
            self.directory(current, depth + 1)


def _archive_layout(data: bytes) -> dict[str, Any]:
    start = 8 if data.startswith(DAT_MAGIC) and data[8:17] == FMF_MAGIC else 0
    if data[start : start + 9] != FMF_MAGIC:
        raise ValueError("no supported embedded resource-FMF signature")
    if len(data) < start + 25:
        raise ValueError("truncated FMF header")
    toc = start + 9 + struct.unpack_from("<Q", data, start + 9)[0]
    base = start + 9 + struct.unpack_from("<Q", data, start + 17)[0]
    if not (start + 26 <= base <= toc < len(data)):
        raise ValueError(f"FMF offsets outside file: base={base}, toc={toc}, len={len(data)}")
    if data[toc : toc + 9] != FMF_MAGIC:
        raise ValueError(f"missing secondary FMF header at 0x{toc:x}")
    directory_bytes = _stream_decompress(data[toc + 9 :], MAX_DIRECTORY_SIZE)
    reader = _DirectoryReader(directory_bytes)
    reader.directory()
    if reader.pos != len(directory_bytes):
        raise ValueError(f"unparsed FMF directory bytes: {len(directory_bytes) - reader.pos}")
    data_limit = toc - base
    for entry in reader.entries:
        if entry["offset"] + entry["packed_size"] > data_limit:
            raise ValueError(f"FMF entry exceeds data region: {entry['path']}")
        if entry["size"] > MAX_ENTRY_SIZE:
            raise ValueError(f"FMF entry exceeds safety limit: {entry['path']}")
    return {
        "container_offset": start,
        "data_base": base,
        "toc_offset": toc,
        "directory_size": len(directory_bytes),
        "entries": reader.entries,
    }


def _read_archive(path: Path) -> tuple[bytes, dict[str, Any]]:
    data = path.read_bytes()
    return data, _archive_layout(data)


def _decompress_entry(data: bytes, base: int, entry: dict[str, Any]) -> bytes:
    start = base + entry["offset"]
    end = start + entry["packed_size"]
    if start < 0 or end > len(data):
        raise ValueError(f"entry outside archive: {entry['path']}")
    raw = _stream_decompress(data[start:end], min(MAX_ENTRY_SIZE, entry["size"]))
    if len(raw) != entry["size"]:
        raise ValueError(
            f"decoded size mismatch for {entry['path']}: {len(raw)} != {entry['size']}"
        )
    return raw


def _archive_path(
    db_path: str | Path | None = None, archive: str = "client_db.dat"
) -> Path:
    if db_path is None:
        return DEFAULT_DB_DIR / archive
    path = Path(db_path)
    if path.is_dir() or not path.suffix:
        return path / archive
    return path


def _entries(
    db_path: str | Path | None = None, archive: str = "client_db.dat"
) -> tuple[Path, bytes, dict[str, Any]]:
    path = _archive_path(db_path, archive)
    if not path.is_file():
        raise FileNotFoundError(path)
    data, layout = _read_archive(path)
    return path, data, layout


def _table_id(entry_path: str) -> int | None:
    match = re.fullmatch(r"table_(\d+)\.dat", PurePosixPath(entry_path).name)
    return int(match.group(1)) if match else None


def _entry_summary(data: bytes, base: int, entry: dict[str, Any]) -> dict[str, Any]:
    summary = dict(entry)
    summary["table_id"] = _table_id(entry["path"])
    summary["entry_type"] = "table" if summary["table_id"] is not None else "auxiliary"
    summary["sha256"] = hashlib.sha256(
        data[base + entry["offset"] : base + entry["offset"] + entry["packed_size"]]
    ).hexdigest()
    if summary["entry_type"] == "table":
        raw = _decompress_entry(data, base, entry)
        if len(raw) >= 12 and raw[:6] == DAT_MAGIC:
            summary["payload_magic"] = raw[:8].hex()
            summary["payload_version"] = struct.unpack_from("<H", raw, 6)[0]
            summary["record_count_header"] = struct.unpack_from("<I", raw, 8)[0]
        hint = TABLE_HINTS.get(summary["table_id"])
        if hint:
            summary["entity_hint"] = hint
    return summary


def list_tables(
    db_path: str | Path | None = None, archive: str = "client_db.dat"
) -> list[dict[str, Any]]:
    """List table and auxiliary entries in a read-only resource archive."""
    _, data, layout = _entries(db_path, archive)
    return [
        _entry_summary(data, layout["data_base"], entry)
        for entry in layout["entries"]
    ]


def _resolve_table(
    table: int | str, entries: list[dict[str, Any]], archive: str = "client_db.dat"
) -> dict[str, Any]:
    selector = str(table)
    if selector.isdecimal():
        selector = f"table_{int(selector)}.dat"
    selector = PurePosixPath(selector).name
    for entry in entries:
        if PurePosixPath(entry["path"]).name == selector:
            return entry
    raise KeyError(f"table not found in {archive}: {table}")


def _read_u32(data: bytes, pos: int, label: str) -> tuple[int, int]:
    if pos + 4 > len(data):
        raise ValueError(f"truncated {label} at 0x{pos:x}")
    return struct.unpack_from("<I", data, pos)[0], pos + 4


def _read_string(data: bytes, pos: int, label: str) -> tuple[str, int]:
    length, pos = _read_u32(data, pos, f"{label} length")
    if length > MAX_STRING_SIZE or pos + length > len(data):
        raise ValueError(f"invalid {label} string length {length} at 0x{pos - 4:x}")
    try:
        value = data[pos : pos + length].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(f"invalid UTF-8 in {label} at 0x{pos:x}") from exc
    return value, pos + length


